result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "kvlite.py", "content": "#!/usr/bin/env python3
"""kvlite: persistent key-value store backed by an append-only log.

Log format (db.log), one record per line, tab-separated:
    SET\\t<key>\\t<base64 value>
    DEL\\t<key>          <- tombstone

State is rebuilt by replaying the log on every invocation.
Compaction rewrites only live entries to a temp file, then atomically
os.replace()s it over the original log.
"""

import base64
import os
import sys
import tempfile

LOG_FILE = "db.log"
SET_OP = "SET"
DEL_OP = "DEL"


def log_path() -> str:
    return os.environ.get("KVLITE_LOG", LOG_FILE)


def load_state(path: str) -> dict:
    """Replay the log and return {key: value} for live entries."""
    state = {}
    if not os.path.exists(path):
        return state
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line:
                continue
            parts = line.split("\t")
            # Tolerate a truncated final record (crash mid-append).
            if parts[0] == SET_OP and len(parts) == 3:
                try:
                    state[parts[1]] = base64.b64decode(parts[2])
                except Exception:
                    continue
            elif parts[0] == DEL_OP and len(parts) == 2:
                state.pop(parts[1], None)
    return state


def append_record(path: str, line: str) -> None:
    with open(path, "a", encoding="utf-8") as f:
        f.write(line + "\n")
        f.flush()
        os.fsync(f.fileno())


def write_compacted(tmp_path: str, state: dict) -> None:
    """Write live entries to tmp_path (no rename)."""
    with open(tmp_path, "w", encoding="utf-8") as f:
        for key in sorted(state):
            val = base64.b64encode(state[key]).decode("ascii")
            f.write(f"{SET_OP}\t{key}\t{val}\n")
        f.flush()
        os.fsync(f.fileno())


def cmd_set(key: str, value: bytes) -> int:
    b64 = base64.b64encode(value).decode("ascii")
    append_record(log_path(), f"{SET_OP}\t{key}\t{b64}")
    return 0


def cmd_get(key: str) -> int:
    state = load_state(log_path())
    if key not in state:
        print(f"error: key not found: {key}", file=sys.stderr)
        return 1
    sys.stdout.buffer.write(state[key])
    if not state[key].endswith(b"\n"):
        sys.stdout.buffer.write(b"\n")
    return 0


def cmd_del(key: str) -> int:
    append_record(log_path(), f"{DEL_OP}\t{key}")
    return 0


def cmd_keys() -> int:
    state = load_state(log_path())
    for key in sorted(state):
        print(key)
    return 0


def cmd_compact() -> int:
    path = log_path()
    state = load_state(path)
    fd, tmp = tempfile.mkstemp(
        prefix=os.path.basename(path) + ".", suffix=".tmp",
        dir=os.path.dirname(os.path.abspath(path)) or ".",
    )
    os.close(fd)
    try:
        write_compacted(tmp, state)
        os.replace(tmp, path)  # atomic swap
    except BaseException:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise
    return 0


def main(argv=None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    if not argv:
        print("usage: kvlite.py {set|get|del|keys|compact} [args]", file=sys.stderr)
        return 2
    cmd, *rest = argv
    try:
        if cmd == "set" and len(rest) == 2:
            return cmd_set(rest[0], rest[1].encode("utf-8"))
        if cmd == "get" and len(rest) == 1:
            return cmd_get(rest[0])
        if cmd == "del" and len(rest) == 1:
            return cmd_del(rest[0])
        if cmd == "keys" and not rest:
            return cmd_keys()
        if cmd == "compact" and not rest:
            return cmd_compact()
    except OSError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print("usage: kvlite.py {set|get|del|keys|compact} [args]", file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main())
"})
